# Simultaneous rounds, input scan order, moving each rectangle one cell when its next footprint is free.
def sim(objs, adjacent=True, maxit=1000):
    # objs list dict r,c,color
    pos=[list(o) for o in objs]
    def collision(k,nr,nc):
        r,c=pos[k]
        for q,(rr,cc) in enumerate(pos):
            if q==k: continue
            # next rect nr,nc vs other current rr,cc
            if adjacent:
                if abs(nr-rr)<=5 and abs(nc-cc)<=5: return True
            else:
                if abs(nr-rr)<5 and abs(nc-cc)<5: return True
        return False
    for it in range(maxit):
        moved=False
        for k,(r,c,col) in enumerate(pos):
            d=-1 if col==8 else 1
            nc=c+d
            if 0<=nc<=17 and not collision(k,r,nc):
                pos[k][1]=nc;moved=True
        if not moved:return pos,it
    return pos,maxit
